package com.hospital.mes.release.application;
import com.fasterxml.jackson.databind.*;import com.fasterxml.jackson.databind.node.*;import java.util.*;
import com.hospital.mes.masterdata.application.*;import com.hospital.mes.production.application.*;import com.hospital.mes.process.application.*;import com.hospital.mes.reporting.application.*;import com.hospital.mes.release.domain.ArchiveCommand;import com.hospital.mes.common.exception.*;
import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.jdbc.support.*;import org.springframework.transaction.annotation.Transactional;
@org.springframework.stereotype.Service @org.springframework.boot.autoconfigure.condition.ConditionalOnProperty(prefix="spring.datasource",name="url")
public class BookService {
 private final JdbcTemplate db;private final ObjectMapper json;private final MasterMutation mutations;private final ProductionQueryService batches;private final ProcessQueryService process;private final MasterQueryService units;private final BookSourceAdapter sources;private final RecordTableDocx word;private final PdfConverter converter;private final PrintService print;private final BookPdfComposer composer;private final EbrArchiveService archive;
 public BookService(JdbcTemplate db,ObjectMapper json,MasterMutation mutations,ProductionQueryService batches,ProcessQueryService process,MasterQueryService units,BookSourceAdapter sources,RecordTableDocx word,PdfConverter converter,PrintService print,BookPdfComposer composer,EbrArchiveService archive){this.db=db;this.json=json;this.mutations=mutations;this.batches=batches;this.process=process;this.units=units;this.sources=sources;this.word=word;this.converter=converter;this.print=print;this.composer=composer;this.archive=archive;}
 @Transactional(readOnly=true) public JsonNode read(String id){return model(MasterMutation.id(id),false);}
 public static String state(BookDefinition.Entry entry,List<? extends JsonNode> documents){if(documents.isEmpty())return entry.required()?"MISSING":"NOT_APPLICABLE";if(documents.size()<entry.minCount())return "MISSING";if(documents.stream().anyMatch(d->d.path("status").asText().equals("DRAFT")))return "DRAFT";if(documents.stream().anyMatch(d->!d.path("status").asText().equals("COMPLETE")))return "PENDING_REVIEW";return "COMPLETE";}
 private ObjectNode model(long batch,boolean strict){var c=mutations.context("ebr:form:view");mutations.context("production:batch:view");var ctx=batches.batch(c.organizationId(),batch);var out=json.createObjectNode().put("mainBatchId",Long.toString(batch)).put("versionNo",ctx.versionNo()).put("status",ctx.status());var fact=batches.batchFact(c.organizationId(),batch);mutations.context("master:uom:view");out.put("unitName",units.unitName(c.organizationId(),fact.path("unitId").asLong()));out.put("batchNo",fact.path("batchNo").asText()).put("plannedQty",fact.path("plannedQty").asText()).put("unitId",fact.path("unitId").asText());mutations.context("master:product:view");var product=process.productLabels(c.organizationId(),fact.path("productId").asLong());out.put("productName",product.productName()).put("specification",product.specification());var book=ctx.snapshot().path("book");out.put("legacy",!book.isObject());if(!book.isObject()){out.putArray("entries");out.put("notice","此批使用原冻结eBR，未自动套用新整册模板。请在原QA批审页面查阅证据归档。");return out;}if(!mutations.digest(book.path("definition")).equals(book.path("definitionHash").asText()))throw new ComplianceException("BOOK_SNAPSHOT_CORRUPT","Frozen directory digest mismatch");var def=BookDefinition.parse(book.path("definition"),json);out.set("book",book.deepCopy());out.put("varietyName",def.varietyName());var entries=out.putArray("entries");for(var e:def.ordered()){var entry=entries.addObject();entry.set("definition",json.valueToTree(e));try{var docs=sources.read(batch,e);entry.put("state",state(e,docs));entry.set("documents",json.valueToTree(docs));}catch(PermissionException denied){if(strict)throw denied;entry.put("state","ACCESS_DENIED");entry.putArray("documents");entry.put("notice","无权读取本项来源记录");}}return out;}
 @Transactional public JsonNode generate(String id,String kind,long version,String reason){var c=mutations.context("ebr:pdf:generate");if(!Set.of("REVIEW_COPY","FINAL").contains(kind)||reason==null||reason.isBlank()||reason.length()>1000)throw new IllegalArgumentException("Exact book archive kind/reason required");long batch=MasterMutation.id(id);var ctx=batches.lockBatch(c.organizationId(),batch);if(ctx.versionNo()!=version)throw new ResourceConflictException("VERSION_CONFLICT","Batch version changed");var model=model(batch,true);if(model.path("legacy").asBoolean())throw new ComplianceException("BOOK_NOT_FROZEN","Legacy batch has no new frozen book; use legacy archive");var book=model.path("book");var def=BookDefinition.parse(book.path("definition"),json);var source=json.createObjectNode();source.set("book",book.deepCopy());source.set("batch",batches.batchFact(c.organizationId(),batch));source.set("entries",BookSourceAdapter.stable(model.path("entries")));source.put("rendererVersion","EBR_BOOK_V5_TOC_LABEL");source.put("converter",converter.getClass().getSimpleName());if(kind.equals("FINAL"))source.put("controlledEvidenceDigest",archive.get(id).path("recordDigest").asText());String sourceHash=mutations.digest(source);var existing=db.queryForList("SELECT id FROM ebr_book_pdf WHERE org_id=? AND main_batch_id=? AND template_version_id=? AND archive_kind=? AND source_hash=?",c.organizationId(),batch,book.path("templateVersionId").asLong(),kind,sourceHash);Long legacy=null;if(kind.equals("FINAL")){for(var item:model.path("entries"))if(item.path("definition").path("required").asBoolean()&&!item.path("state").asText().equals("COMPLETE"))throw new ComplianceException("BOOK_REQUIRED_ENTRY_INCOMPLETE","Required entry incomplete: "+item.path("definition").path("code").asText());legacy=archive.generate(id,new ArchiveCommand(version,"FINAL",reason),'"'+Long.toString(version)+'"',"book-final-"+java.util.UUID.randomUUID()).path("id").asLong();}
  if(!existing.isEmpty())return manifest(c.organizationId(),batch,((Number)existing.getFirst().get("id")).longValue());var parts=new ArrayList<BookPdfComposer.Part>();for(var entry:model.path("entries")){var e=json.convertValue(entry.path("definition"),BookDefinition.Entry.class);if(entry.path("documents").isEmpty()){parts.add(new BookPdfComposer.Part(e.chapter()+" / "+e.title(),converter.convert(word.create(e.title(),kind.equals("FINAL")?"正式归档":"草稿",List.of("目录状态","说明"),List.of(List.of(entry.path("state").asText(),e.required()?"必需记录未齐全":"本批无此项来源记录"))))));continue;}for(var doc:entry.path("documents")){byte[] pdf;if(e.kind().equals("FORM")&&e.printTemplateVersionId()!=null){var data=print.provider("EBR_PROCESS_FORM").load(doc.path("formId").asText(),kind.equals("FINAL")).data();var selected=new LinkedHashMap<String,Object>(data);Object items=data.get("items");if(items instanceof List<?> rows)selected.put("items",rows.stream().filter(x->x instanceof Map<?,?> map&&e.fields().contains(String.valueOf(map.get("fieldCode")))).toList());pdf=print.renderFrozen(e.printTemplateVersionId(),"EBR_PROCESS_FORM",selected);}else{List<String> columns=new ArrayList<>();doc.path("columns").forEach(x->columns.add(x.asText()));var rows=new ArrayList<List<String>>();for(var row:doc.path("rows")){var values=new ArrayList<String>();row.forEach(x->values.add(x.asText()));rows.add(values);}rows.add(new ArrayList<>(List.of("来源版本",doc.path("sourceVersion").asText())));pdf=converter.convert(word.create(doc.path("title").asText(),kind.equals("FINAL")?"正式归档":"草稿 · 非正式记录",columns,rows));}parts.add(new BookPdfComposer.Part(e.chapter()+" / "+doc.path("title").asText(),pdf));if(e.kind().equals("ATTACHMENTS")){var file=sources.attachment(doc.path("sourceId").asText());String media=file.metadata().mediaType();byte[] appendix;if(media.equals("application/pdf"))appendix=file.content();else if(Set.of("image/png","image/jpeg").contains(media))appendix=composer.imageAttachment(file.content());else throw new ComplianceException("BOOK_ATTACHMENT_FORMAT_UNSUPPORTED","Book appendix supports PDF/PNG/JPEG; original retained: "+file.metadata().fileName());parts.add(new BookPdfComposer.Part("附件原件副本 / "+file.metadata().fileName(),appendix));}}
  }
  var manifestRows=new ArrayList<List<String>>();for(var entry:model.path("entries"))for(var doc:entry.path("documents"))manifestRows.add(List.of(entry.path("definition").path("code").asText(),doc.path("sourceType").asText(),doc.path("sourceId").asText(),doc.path("sourceVersion").asText(),doc.path("sourceHash").asText()));parts.add(new BookPdfComposer.Part("证据版本清单",converter.convert(word.create("证据版本清单",sourceHash,List.of("目录项","来源类型","来源ID","来源版本","SHA-256"),manifestRows))));if(legacy!=null){var legacyManifest=archive.manifest(id,legacy.toString());var file=sources.attachment(legacyManifest.path("fileId").asText());parts.add(new BookPdfComposer.Part("受控原始证据附录",file.content()));}
  byte[] pdf=composer.compose(List.of("品种："+model.path("varietyName").asText(),"品名："+model.path("productName").asText(),"规格："+model.path("specification").asText(),"批号："+model.path("batchNo").asText(),"批量："+model.path("plannedQty").asText()+" "+model.path("unitName").asText(),"模板版本："+book.path("templateVersionId").asText()+" / "+book.path("templateRevision").asText()),parts,kind);var keys=new GeneratedKeyHolder();Long evidence=legacy;db.update(conn->{var s=conn.prepareStatement("INSERT INTO ebr_book_pdf(org_id,main_batch_id,template_version_id,template_hash,source_hash,manifest_json,pdf,pdf_hash,archive_kind,legacy_manifest_id,created_by) VALUES(?,?,?,?,?,?,?,?,?,?,?)",java.sql.Statement.RETURN_GENERATED_KEYS);s.setLong(1,c.organizationId());s.setLong(2,batch);s.setLong(3,book.path("templateVersionId").asLong());s.setString(4,book.path("definitionHash").asText());s.setString(5,sourceHash);s.setString(6,source.toString());s.setBytes(7,pdf);s.setString(8,PrintService.hash(pdf));s.setString(9,kind);if(evidence==null)s.setNull(10,java.sql.Types.BIGINT);else s.setLong(10,evidence);s.setLong(11,c.actorId());return s;},keys);long artifact=Objects.requireNonNull(keys.getKey()).longValue();var result=manifest(c.organizationId(),batch,artifact);mutations.auditSnapshot(c,"EBR_BOOK_PDF_GENERATE","EbrBookPdf",artifact,null,result,reason,null);return result;
 }
 @Transactional(readOnly=true) public JsonNode history(String id){var c=mutations.context("ebr:form:view");long batch=MasterMutation.id(id);model(batch,true);var out=json.createArrayNode();for(var row:db.queryForList("SELECT id FROM ebr_book_pdf WHERE org_id=? AND main_batch_id=? ORDER BY id DESC",c.organizationId(),batch))out.add(manifest(c.organizationId(),batch,((Number)row.get("id")).longValue()));return out;}
 @Transactional(readOnly=true) public byte[] pdf(String batchId,String id){var c=mutations.context("ebr:form:view");mutations.context("production:batch:view");mutations.context("master:product:view");long batch=MasterMutation.id(batchId),artifact=MasterMutation.id(id);batches.batch(c.organizationId(),batch);var rows=db.queryForList("SELECT * FROM ebr_book_pdf WHERE org_id=? AND main_batch_id=? AND id=?",c.organizationId(),batch,artifact);if(rows.isEmpty())throw new NoSuchElementException("Book PDF not found");var row=rows.getFirst();var saved=parse(row.get("manifest_json"));for(var entry:saved.path("entries"))sources.read(batch,json.convertValue(entry.path("definition"),BookDefinition.Entry.class));byte[] pdf=(byte[])row.get("pdf");if(!PrintService.hash(pdf).equals(row.get("pdf_hash")))throw new ComplianceException("BOOK_PDF_CORRUPT","Archived PDF hash mismatch");return pdf.clone();}
 private ObjectNode manifest(long org,long batch,long id){var r=db.queryForMap("SELECT id,main_batch_id,template_version_id,template_hash,source_hash,pdf_hash,archive_kind,legacy_manifest_id,created_by,created_at FROM ebr_book_pdf WHERE org_id=? AND main_batch_id=? AND id=?",org,batch,id);var n=json.createObjectNode();r.forEach((k,v)->{if(v==null)n.putNull(k);else n.put(k,v.toString());});return n;}
 private JsonNode parse(Object s){try{return json.readTree(s.toString());}catch(Exception e){throw new IllegalStateException("Retained manifest corrupt",e);}}
}
